def f(g):
    H,W=len(g),len(g[0])
    rows={i for i in range(H) if sum(1 for j in range(W) if g[i][j])>W/2}
    cols={j for j in range(W) if sum(1 for i in range(H) if g[i][j])>H/2}
    def pick(n,colored):
        res=[];prev=-1
        for c in sorted(colored)+[n]:
            gap=list(range(prev+1,c))
            if gap: res.append(gap[0])
            if c<n: res.append(c)
            prev=c
        return res
    R=pick(H,rows);C=pick(W,cols)
    return [[g[r][c] for c in C] for r in R]
